const fileSignature = async file => { try { const bytes = await file.arrayBuffer(); const hash = await crypto.subtle.digest('SHA-256',bytes); return [...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join(''); } catch { return ''; } };
function DatasetManager({ files, onImport, onExport, go }) { const [search,setSearch]=useState('');const [filter,setFilter]=useState('All files');const [folder,setFolder]=useState(''); const shown=files.filter(f=>(f.name.toLowerCase().includes(search.toLowerCase()))&&(filter==='All files'||(filter==='Originals'&&f.type?.startsWith('image/')))); return <><Banner tone={files.length?'blue':'blue'} title={files.length?'Local browser files imported':'No dataset has been imported'}>{files.length?`${files.length} local image file(s) loaded into this browser session. This is not a validated satellite source, backend manifest, or authorized filesystem adapter.`:'Source and output directories are not configured. JPEG / TIFF scope, band decoding and maximum image size depend on an implemented image adapter.'}</Banner><div className="dataset-layout space-top"><Panel title="Folders & categories" right={files.length?'LOCAL FILES':'EMPTY'}><Field label="Find a folder" value={folder} onChange={setFolder} placeholder="Search..."/><div className="folder-tree"><div>▾ Trusted originals</div><p>{files.length ? `${files.length} browser image(s)` : 'No source directory'}</p><div>▾ Derived artifacts</div><p>No output directory</p><div>▾ Categories</div><p>No categories imported</p></div><div className="mini-key space-top">SOURCE READ-ONLY</div><p className="muted">Imported folders and categories will appear here without changing originals.</p></Panel><div><Panel title="Dataset manifest" right={`${shown.length} LOCAL FILE RECORDS`}><Field label="Search manifest" value={search} onChange={setSearch} placeholder="Search path, category or hash..."/><div className="chip-row space-top">{['All files','Originals','Attacked outputs','Masks','Unpaired'].map(x=><button className={`chip ${x===filter?'selected':''}`} key={x} onClick={()=>setFilter(x)}>{x}</button>)}</div><div className="data-table space-top"><div className="table-head" style={{gridTemplateColumns:'2fr 1fr 1fr 1fr 1.8fr 1fr'}}>{['PATH','CATEGORY','FORMAT','BANDS','HASH','PAIR STATUS'].map(x=><span key={x}>{x}</span>)}</div>{shown.length ? shown.map(f=><div className="data-row" key={f.id} style={{gridTemplateColumns:'2fr 1fr 1fr 1fr 1.8fr 1fr'}}><span title={f.name}>{f.name}</span><span>Local source</span><span>{f.type?.split('/').pop()?.toUpperCase()||'File'}</span><span>—</span><span title={f.hash}>{f.hash ? `${f.hash.slice(0,12)}…`:'pending'}</span><span>Unpaired</span></div>) : <div className="empty-table" style={{minHeight:245}}><span>No manifest entries</span><p>Import a local image file or connect an authorized image adapter.</p></div>}<div className="table-footer"><span>{shown.length} LOCAL RECORDS</span><span>Previous / Next</span></div></div><div className="row space-top"><Button icon={Upload} onClick={onImport}>Choose image files</Button><Button icon={FileJson} onClick={onExport} disabled={!files.length}>Export local manifest</Button></div></Panel><Panel title="Original / attacked pairs & masks" right="NO PAIRED ARTIFACTS" className="space-top"><div className="field-grid three"><NoData title="NO PAIRED ORIGINAL" icon={Image}/><NoData title="NO ATTACKED OUTPUT" icon={FileImage}/><NoData title="NO MASK" icon={Crosshair}/></div><SmallNote>Pairing requires a shared source reference and validated dimensions. No attack output or mask records are available.</SmallNote></Panel></div><Panel title="Import configuration" right="NOT CONFIGURED"><Field label="Source originals directory" value="" placeholder="Not configured"/><SmallNote>Read-only boundary. Originals must never be overwritten.</SmallNote><Field label="Artifact output directory" value="" placeholder="Not configured"/><SmallNote>Must be separate from trusted source storage.</SmallNote><Field label="Image adapter" value="" placeholder="Unavailable"/><Field label="Maximum image size" value="" placeholder="Unset"/><Kvp label="Format scope" value="JPEG / TIFF"/><Kvp label="Band support" value="Unknown"/><Kvp label="Hash validation" value={files.length?'Local SHA-256':'Unavailable'}/><Banner title="Backend import not ready">Connect an authorized filesystem / image adapter and configure storage boundaries before processing or pairing.</Banner><Button onClick={()=>go('System Settings')}>Configure source</Button></Panel></div><Panel title="Batch processing queue" right="EMPTY / NO WORK SCHEDULED" className="space-top"><TableEmpty columns={['SOURCE','OPERATION','OUTPUT','PAIR STATUS','STATE']} message="No queued files" detail="A validated manifest and processing adapter are required. No originals are modified." height={120}/></Panel></>; }
function AnalyticsReports({go}) {const [title,setTitle]=useState('');const [stage,setStage]=useState('All stages');const [severity,setSeverity]=useState('All severities');const [checked,setChecked]=useState(['Experiment scope & authorization','Attack / stage configuration','Execution outcomes','Ground verification evidence','Image quality measurements','Artifact & provenance appendix']); return <><Panel title="Experimental dataset" right="NO DATASET"><div className="field-grid four"><Field label="Dataset" value="" placeholder="No saved experiment dataset"/><Select label="Stage filter" options={['All stages','Onboard','Transit']} value={stage} onChange={setStage}/><Select label="Severity filter" options={['All severities','Low','Medium','High']} value={severity} onChange={setSeverity}/><div className="field"><span>Analysis</span><Button disabled icon={RefreshCcw}>Refresh analysis</Button></div></div></Panel><div className="metric-grid space-top">{[['Saved records','0'],['Success',dash],['Bypass',dash],['Detection',dash],['Rejection',dash],['Latency',dash],['PSNR',dash],['SSIM',dash]].map(([k,v])=><div className="metric" key={k}><span>{k}</span><b>{v}</b></div>)}</div><div className="columns main-aside space-top"><div><Panel title="Attack versus defense matrix" right="STRUCTURE ONLY / NO DATA"><div className="data-table"><div className="table-head" style={{gridTemplateColumns:'1.4fr repeat(5,1fr)'}}>{['ATTACK / STAGE','AUTHENTICATION','INTEGRITY','REPLAY','CONTENT','DECISION'].map(x=><span key={x}>{x}</span>)}</div><NoData title="NO DATA / NO SAMPLES" tall>Real registry identifiers will form rows after correlated ground evidence is saved.</NoData><div className="table-footer"><span>NO COUNTS OR RATES COMPUTED</span><span>TIME RANGE — / SOURCE NOT AVAILABLE</span></div></div></Panel><Panel title="Performance by attack & stage" right="NO AGGREGATES" className="space-top"><TableEmpty columns={['ATTACK','STAGE','RECORDS','GROUND EVIDENCE','LATENCY','PSNR / SSIM']} message="No performance records" detail="Unavailable metrics are not treated as zero." height={125}/></Panel><Panel title="Experiment timeline" right="TIMELINE UNAVAILABLE" className="space-top"><div className="chip-row"><Tag>Ground verdict</Tag><Tag>Execution</Tag><Tag>Latency</Tag></div><NoData icon={Activity} tall title="No attack and ground-evidence pairs">No timestamped experiment records. No values or curves are plotted.</NoData></Panel></div><div><Panel title="Report builder" right="AWAITING DATA"><Field label="Report title" value={title} onChange={setTitle} placeholder="Not set"/><div className="mini-key space-top">INCLUDE SECTIONS / CONFIGURATION ONLY</div>{['Experiment scope & authorization','Attack / stage configuration','Execution outcomes','Ground verification evidence','Image quality measurements','Artifact & provenance appendix'].map(x=><label className="check-label" key={x}><input type="checkbox" checked={checked.includes(x)} onChange={e=>setChecked(p=>e.target.checked?[...p,x]:p.filter(t=>t!==x))}/>{x}</label>)}<Kvp label="Evidence scope" value="No saved records"/><div className="row space-top"><Button disabled>CSV</Button><Button disabled>JSON</Button><Button disabled>PDF</Button></div><SmallNote>Export requires saved data and an implemented report adapter. No report has been generated.</SmallNote></Panel><Panel title="Metric interpretation" right="EVIDENCE REQUIRED" className="space-top"><strong>Confirmed bypass denominator</strong><p className="muted">Only experiments with actual, interpretable ground evidence can enter a confirmed bypass denominator. A local execution outcome alone is insufficient.</p><Kvp label="Eligible evidence population" value="Unavailable"/><SmallNote>No misleading zero-percent results: rates remain —.</SmallNote><Button onClick={()=>go('Experiments')}>Open experiments</Button></Panel></div></div></>; }
