function SystemSettings({ config, setConfig, notice, showNotice }) { const [tab,setTab]=useState('Integrations');const [draftAllow,setDraftAllow]=useState('');const update=(key,value)=>setConfig(v=>({...v,[key]:value}));const cfgField=(label,key,placeholder='Not configured')=><Field label={label} value={config[key]} onChange={v=>update(key,v)} placeholder={placeholder}/>;
 const endpoint=(title,prefix,description)=> <Panel title={title} right="NOT CONNECTED"><SmallNote>{description}</SmallNote><div className="field-grid host-port space-top">{cfgField('Authorized host / IP',prefix+'Host')}{cfgField('Port',prefix+'Port')}</div>{cfgField('Transport / protocol',prefix+'Protocol','Existing implementation required')}<div className="row spread space-top"><Tag>CHECK PENDING</Tag><Button disabled>Test connection</Button></div></Panel>;
 return <div className="settings-layout"><aside className="settings-tabs">{settingsTabs.map(x=><button className={x===tab?'active':''} key={x} onClick={()=>setTab(x)}>{x}</button>)}<div className="mini-key space-top">CONFIGURATION STATE</div><Tag tone="amber">NOT CONFIGURED</Tag><p>No live endpoint or adapter has been verified.</p></aside><div className="settings-content">{tab==='Integrations'&&<><Panel title="Lab environment" right="LIVE LAB SELECTED"><div className="chip-row"><Tag tone="blue">LIVE LAB / selected</Tag><Tag>DEMO / inactive</Tag></div><p className="muted">LIVE LAB requires real, authorized adapters. DEMO is an inactive isolated simulation concept; never mix simulated records with live evidence.</p></Panel><div className="columns two space-top">{endpoint('Satellite','satellite','Satellite Team / Raspberry Pi capture and telemetry')}{endpoint('Ground station','ground','Ground Team / receiver and defense response source')}{endpoint('Attacker relay','relay','Authorized TCP route / no relay implementation connected')}<Panel title="Attack registry adapter" right="UNAVAILABLE"><SmallNote>Actual identifiers, functions and parameter schema require existing integration.</SmallNote>{cfgField('Adapter implementation / module','registryModule')}{cfgField('Registry loading contract','registryContract','Existing implementation required')}<Tag>CHECK PENDING</Tag><Button disabled>Validate adapter</Button></Panel></div><Panel title="Transport & event defaults" right="UNSET" className="space-top"><div className="field-grid three">{cfgField('WebSocket retry interval','retryInterval','Unset')}{cfgField('Maximum retries','maxRetries','Unset')}{cfgField('Connection timeout','connectionTimeout','Unset')}</div><div className="columns two space-top"><SmallNote>Safe fallback: PASS intended. Offline, implemented adapter must honor failure behavior.</SmallNote><SmallNote>Allowlisted commands only. No arbitrary shell access.</SmallNote></div></Panel></>}
 {tab==='Lab authorization'&&<Panel title="Authorized endpoint allowlist" right={`${config.allowlist.length} UNVERIFIED ENTRY/ENTRIES`}><p className="muted">Saving an endpoint is not authorization to connect, intercept or execute. Independent approval and backend enforcement are required.</p><div className="row space-top"><input className="full-input" aria-label="Approved endpoint" placeholder="Approved host / IP" value={draftAllow} onChange={e=>setDraftAllow(e.target.value)}/><Button icon={Plus} onClick={()=>{if(draftAllow.trim() && !config.allowlist.includes(draftAllow.trim())){update('allowlist',[...config.allowlist,draftAllow.trim()]);setDraftAllow('');}}}>Add locally</Button></div>{config.allowlist.map(h=><div className="kvp" key={h}><span>{h}</span><Button subtle icon={X} onClick={()=>update('allowlist',config.allowlist.filter(x=>x!==h))}>Remove</Button></div>)}{!config.allowlist.length&&<NoData title="NO ENTRIES">No destination is authorized for execution.</NoData>}</Panel>}
 {tab==='Data & storage'&&<Panel title="Data & storage" right="NOT CONFIGURED">{cfgField('Trusted originals directory','sourceDir')}{cfgField('Derived artifact directory','outputDir')}{cfgField('Maximum image dimensions','maxDimensions','Unset')}{cfgField('Maximum file size','maxFileSize','Unset')}<Banner title="Storage boundaries">Trusted originals must remain read-only. An output destination must be separate and validated by a real image adapter.</Banner></Panel>}
 {tab==='Terminal'&&<Panel title="Terminal controls" right="DOCUMENTATION MODE"><Kvp label="Shell access" value="Disabled"/><Kvp label="Command type" value="Allowlisted documentation"/><Kvp label="Execution" value="Unavailable"/><p className="muted">The frontend has no operating-system shell or adapter. Terminal entries are text only.</p></Panel>}
 {tab==='Events'&&<Panel title="Event sources" right="NO SOURCE"><Kvp label="Satellite telemetry" value="Disconnected"/><Kvp label="Ground-station response" value="Disconnected"/><Kvp label="Transport events" value="Disconnected"/><Kvp label="UTC clock source" value="Unavailable"/><NoData title="NO LIVE EVENTS">A real backend is required to subscribe to correlated event streams.</NoData></Panel>}
 {tab==='Appearance'&&<Panel title="Appearance" right="BLACK PIXEL"><Kvp label="Theme" value="Dark / fixed"/><Kvp label="Interface typography" value="System + monospace"/><Kvp label="Layout" value="Responsive"/><p className="muted">Design language reproduced from the supplied PDF dashboards.</p></Panel>}
 {tab==='Audit'&&<Panel title="Audit history" right="0 BACKEND RECORDS"><TableEmpty columns={['UTC','ACTOR','CONFIGURATION CHANGE','SCOPE','RESULT']} message="No audit records" detail="A connected audit service is needed for authoritative, tamper-evident logs." height={160}/></Panel>}
 <div className="row space-top"><Button icon={Check} onClick={()=>{try{localStorage.setItem('blackpixel-config',JSON.stringify(config));showNotice('Configuration saved in this browser only. No backend connection was established.');}catch{showNotice('Browser storage is unavailable.')}}}>Save locally</Button><Button disabled>Run integration checks</Button><SmallNote>Local drafts do not establish connections or authorization.</SmallNote></div>{notice&&<div className="save-notice">{notice}</div>}</div><aside className="settings-right"><Panel title="Lab authorization" right="NO VERIFIED ALLOWLIST"><div className="mini-key">Authorized endpoint allowlist</div><NoData title={config.allowlist.length?`${config.allowlist.length} LOCAL ENTRIES`:'NO ENTRIES'}>No destination is authorized for execution.</NoData><Button onClick={()=>setTab('Lab authorization')}>Manage allowlist</Button><Kvp label="Integration checks" value="Pending"/></Panel><Panel title="Data & storage" right="NOT CONNECTED" className="space-top"><Kvp label="Trusted originals" value={config.sourceDir||'Not configured'}/><Kvp label="Derived directory" value={config.outputDir||'Not configured'}/><SmallNote>JPEG / TIFF support and storage access depend on adapters.</SmallNote></Panel><Panel title="Secrets & trust boundary" right="NO SECRETS PRESENT" className="space-top"><Kvp label="Stored credentials" value="None"/><Kvp label="Ground signing keys" value="Inaccessible"/><SmallNote>This frontend does not have access to signing material. Never import signing keys into attack configuration.</SmallNote></Panel></aside></div>;
}
function App() {
 const [page,setPage]=useState('Command Center');const [mobileOpen,setMobileOpen]=useState(false);
 const [terminal,setTerminal]=useState({input:'',docs:[]});const [config,setConfig]=useState(getSavedConfig);const [files,setFiles]=useState([]);const [notice,setNotice]=useState(''); const filePicker=useRef(null);
 useEffect(()=>{const hash=window.location.hash.slice(1);const match=Object.keys(DESCRIPTIONS).find(x=>slug(x)===hash);if(match)setPage(match);},[]);
 const go=next=>{setPage(next);window.history.replaceState(null,'',`#${slug(next)}`);window.scrollTo({top:0,behavior:'instant'});setMobileOpen(false);};
 const importFiles=async selected=>{ const imgs=[...selected].filter(f=>/^image\/(jpeg|png|tiff|webp|gif)$/.test(f.type)||/\.(jpe?g|png|tiff?|webp|gif)$/i.test(f.name));const bounded=imgs.slice(0,50).filter(f=>f.size<=25*1024*1024); if(!bounded.length){setNotice('Choose JPEG, PNG, WebP or TIFF image files (maximum 25 MB each).');return;}const added=await Promise.all(bounded.map(async (f,i)=>{const url=URL.createObjectURL(f);let width=null,height=null;try{const img=new window.Image();img.src=url;await img.decode();width=img.naturalWidth;height=img.naturalHeight;}catch{}return {id:`${Date.now()}-${i}-${f.name}`,name:f.name,size:f.size,type:f.type||'image/unknown',hash:await fileSignature(f),url,width,height,importedAt:new Date().toISOString()};}));setFiles(prev=>[...prev,...added]);setNotice(`${added.length} image(s) imported into the browser only. No live dataset adapter was connected.`); };
 const exportManifest=()=>{const data={note:'LOCAL BROWSER PREVIEW - not a verified satellite/ground manifest',createdAt:new Date().toISOString(),files:files.map(({url,...f})=>f)};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const link=document.createElement('a');const url=URL.createObjectURL(blob);link.href=url;link.download='black-pixel-local-manifest.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 const onImport=()=>filePicker.current?.click();
 let content;
 switch(page){
 case 'Command Center':content=<CommandCenter go={go} config={config} terminal={terminal} setTerminal={setTerminal} files={files}/>;break;
 case 'Attack Terminal':content=<AttackTerminal go={go} terminal={terminal} setTerminal={setTerminal}/>;break;
 case 'Satellite Monitor':content=<SatelliteMonitor go={go} config={config}/>;break;
 case 'TCP Network Operations':content=<TCPNetwork config={config} go={go}/>;break;
 case 'Attack Arsenal':content=<AttackArsenal go={go}/>;break;
 case 'Image Laboratory':content=<ImageLaboratory files={files} go={go}/>;break;
 case 'Defense Intelligence':content=<DefenseIntelligence go={go}/>;break;
 case 'Experiments':content=<Experiments go={go} files={files}/>;break;
 case 'Dataset Manager':content=<DatasetManager files={files} onImport={onImport} onExport={exportManifest} go={go}/>;break;
 case 'Analytics & Reports':content=<AnalyticsReports go={go}/>;break;
 case 'Mission Replay':content=<MissionReplay go={go}/>;break;
 case 'System Settings':content=<SystemSettings config={config} setConfig={setConfig} notice={notice} showNotice={setNotice}/>;break;
 default:content=null;
 }
 return <div className="app"><Sidebar page={page} go={go} isOpen={mobileOpen} onClose={()=>setMobileOpen(false)}/><div className="app-main"><div className="mobile-top"><button onClick={()=>setMobileOpen(true)} aria-label="Open menu"><Menu/></button><b>BLACK PIXEL</b><Tag tone="amber">OFFLINE</Tag></div><TopChrome/><main className="page-content"><PageTitle page={page} go={go} onImport={onImport} onReview={()=>setNotice('Review endpoint approval, satellite and ground adapters, the registry, transport framing and isolated artifact storage before connecting a live lab.')}/>{content}</main><AppFooter/></div><input type="file" ref={filePicker} accept="image/png,image/jpeg,image/tiff,image/webp,image/gif,.tif,.tiff" multiple hidden onChange={e=>{importFiles(e.target.files);e.target.value='';}}/>{notice&&page!=='System Settings'&&<div className="toast" role="status"><span>{notice}</span><button onClick={()=>setNotice('')} aria-label="Dismiss notification"><X size={15}/></button></div>}</div>;
}
function slug(x){return x.toLowerCase().replace(/&/g,'and').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');}
export default App;
